CREATE TABLE courses(id BIGINT PRIMARY KEY,retraining_policy_id BIGINT,occurrence_number INT,title VARCHAR(200),description TEXT,course_type VARCHAR(20),status VARCHAR(20),start_date DATE,end_date DATE,passing_progress_rate DECIMAL(5,2),instructor_id BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE assignment_rules(id BIGINT PRIMARY KEY,course_id BIGINT,department_id BIGINT,job_position_id BIGINT,new_employee_days SMALLINT,rule_type VARCHAR(30),is_active BOOLEAN,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE members(id BIGINT PRIMARY KEY,employee_number VARCHAR(50),email VARCHAR(255),password_hash VARCHAR(255),name VARCHAR(100),department_id BIGINT,job_position_id BIGINT,status VARCHAR(20),hire_date DATE,resigned_at TIMESTAMP,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE enrollments(id BIGINT PRIMARY KEY,member_id BIGINT,course_id BIGINT,status VARCHAR(20),assignment_source VARCHAR(20),assignment_rule_id BIGINT,assigned_at TIMESTAMP,started_at TIMESTAMP,completed_at TIMESTAMP,due_date DATE,version BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id BIGINT NOT NULL REFERENCES members(id),enrollment_id BIGINT NOT NULL REFERENCES enrollments(id),type VARCHAR(30) NOT NULL,title VARCHAR(100) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP NOT NULL,read_at TIMESTAMP,CONSTRAINT uk_notifications_enrollment_type UNIQUE(enrollment_id,type));
CREATE TABLE push_subscriptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id BIGINT NOT NULL REFERENCES members(id),endpoint VARCHAR(2048) NOT NULL,endpoint_hash VARCHAR(64) NOT NULL UNIQUE,p256dh VARCHAR(100) NOT NULL,auth VARCHAR(32) NOT NULL,enabled BOOLEAN NOT NULL,expiration_time TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,version BIGINT NOT NULL DEFAULT 0);
